  return (
    <nav
      className={`fixed top-0 left-0 w-full z-50 transition-all duration-500 ${
        isScrolled ? "bg-brand-emerald shadow-lg py-3" : "bg-transparent py-5"
      }`}
    >
      <div className="container mx-auto px-6 flex items-center justify-between">
        {/* Mobile Menu Icon */}
        <div className="lg:hidden">
          <button
            onClick={() => setIsMobileMenuOpen(true)}
            className="text-white p-2"
          >
            <Menu className="w-6 h-6" />
          </button>
        </div>

        {/* Navigation Links - Desktop */}
        <div className="hidden lg:flex items-center space-x-8">
          {navLinks.map((link) => (
            <Link
              key={link.name}
              href={link.href}
              className="text-white hover:text-brand-gold transition-colors text-sm uppercase tracking-widest font-medium"
            >
              {link.name}
            </Link>
          ))}
        </div>

        {/* Brand Name */}
        <Link
          href="/"
          className="absolute left-1/2 -translate-x-1/2 text-center"
        >
          <span className="text-xl md:text-2xl font-serif font-bold tracking-[0.2em] text-white whitespace-nowrap block">
            GEMS OF
          </span>
          <span className="text-sm md:text-md font-serif font-medium tracking-[0.5em] text-brand-gold whitespace-nowrap block mt-[-4px]">
            mairii
          </span>
        </Link>

        {/* Icons Section */}
        <div className="flex items-center space-x-4 md:space-x-6 text-white">
          <button className="hover:text-brand-gold transition-colors hidden md:block">
            <Search className="w-5 h-5" />
          </button>
          <Link href="/profile" className="hover:text-brand-gold transition-colors hidden md:block">
            <User className="w-5 h-5" />
          </Link>
          <Link href="/profile#wishlist" className="hover:text-brand-gold transition-colors">
            <Heart className="w-5 h-5" />
          </Link>
          <Link href="/cart" className="relative group hover:text-brand-gold transition-colors">
            <ShoppingBag className="w-5 h-5" />
            {cart.length > 0 && (
              <span className="absolute -top-2 -right-2 bg-brand-gold text-brand-emerald text-[10px] font-bold w-4 h-4 flex items-center justify-center rounded-full">
                {cart.length}
              </span>
            )}
          </Link>
        </div>
      </div>

      {/* Mobile Menu Overlay */}
      <AnimatePresence>
        {isMobileMenuOpen && (
          <>
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setIsMobileMenuOpen(false)}
              className="fixed inset-0 bg-black/60 z-[60]"
            />
            <motion.div
              initial={{ x: "-100%" }}
              animate={{ x: 0 }}
              exit={{ x: "-100%" }}
              transition={{ type: "spring", damping: 25, stiffness: 200 }}
              className="fixed top-0 left-0 h-full w-[280px] bg-brand-emerald z-[70] p-8 shadow-2xl"
            >
              <div className="flex justify-between items-center mb-12">
                <span className="font-serif text-brand-gold text-lg font-bold tracking-widest">
                  MENU
                </span>
                <button
                  onClick={() => setIsMobileMenuOpen(false)}
                  className="text-white"
                >
                  <X className="w-6 h-6" />
                </button>
              </div>

              <div className="flex flex-col space-y-6">
                {navLinks.map((link) => (
                  <Link
                    key={link.name}
                    href={link.href}
                    onClick={() => setIsMobileMenuOpen(false)}
                    className="text-white hover:text-brand-gold text-xl font-serif tracking-widest"
                  >
                    {link.name}
                  </Link>
                ))}
                <div className="pt-10 flex flex-col space-y-4">
                  <Link href="/profile" className="flex items-center space-x-4 text-white">
                    <User className="w-5 h-5" />
                    <span className="text-sm uppercase tracking-widest">Profile</span>
                  </Link>
                  <Link href="/profile#wishlist" className="flex items-center space-x-4 text-white">
                    <Heart className="w-5 h-5" />
                    <span className="text-sm uppercase tracking-widest">Wishlist</span>
                  </Link>
                </div>
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>
    </nav>
  );
};

